import random

# Initialize the game board as a 2D list of empty cells
BOARD = [[' ' for _ in range(3)] for _ in range(3)]

def print_board():
    """Print the current game board."""
    print('   |   |')
    print(' ' + '-' * 6 + ' ')

    for row in BOARD:
        print(' ' + ' | '.join(row) + ' ')
        print('   |   |')
        print('-' * 12 + ' ')

def get_user_move():
    """Get a valid user move."""
    while True:
        move = input('Enter your move (e.g. 1 2): ').strip()
        try:
            row, col = map(int, move.split())
            if 0 < row <= 3 and 0 < col <= 3 and BOARD[row - 1][col - 1] == ' ':
                return row, col
            else:
                print('Invalid move. Please enter a number between 1 and 3.')
        except ValueError:
            print('Invalid move. Please enter two numbers separated by a space.')

def make_computer_move():
    """Generate a random move for the computer."""
    return random.randint(1, 9)

def check_winner():
    """Check if there's a winner."""
    for row in BOARD:
        if row[0] != ' ' or row[1] != ' ' or row[2] != ' ':
            if row[0] == row[1] == row[2]:
                return row[0]

    for col in range(3):
        if BOARD[0][col] != ' ' or BOARD[1][col] != ' ' or BOARD[2][col] != ' ':
            if BOARD[0][col] == BOARD[1][col] == BOARD[2][col]:
                return BOARD[0][col]

    if BOARD[0][0] != ' ' or BOARD[1][1] != ' ' or BOARD[2][2] != ' ':
        if BOARD[0][0] == BOARD[1][1] == BOARD[2][2]:
            return BOARD[0][0]

    if BOARD[2][0] != ' ' or BOARD[1][1] != ' ' or BOARD[0][2] != ' ':
        if BOARD[2][0] == BOARD[1][1] == BOARD[0][2]:
            return BOARD[2][0]

    return None

def play_game():
    """Play a single game of Tic Tac Toe."""
    current_player = 'X'
    while True:
        print_board()
        row, col = get_user_move()
        BOARD[row - 1][col - 1] = current_player

        if check_winner():
            print_board()
            print('You won! Congratulations!')
            return

        if ' ' not in ''.join(''.join(row) for row in BOARD):
            print_board()
            print('It\'s a draw!')
            return

        current_player = 'O' if current_player == 'X' else 'X'

# Start the game
play_game()
